import { Component, Output, EventEmitter, inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NewsSource } from 'src/app/news-source/news-source.model';

// import * as mediaData from 'BalancedMediaDiet.json';
import { NZ_MODAL_DATA } from 'ng-zorro-antd/modal';

@Component({
  selector: 'grid-news-source',
  templateUrl: './grid-news-source.component.html',
  styleUrls: ['./grid-news-source.component.css'],
})
export class GridNewsSourceComponent {
  @Output() edit = new EventEmitter<NewsSource>();
  readonly nzModalData = inject(NZ_MODAL_DATA);

  newsOrg: NewsSource;

  constructor(private route: ActivatedRoute) {}

  ngOnInit() {
    console.log('Incoming data to the modal: ', this.nzModalData);
    this.newsOrg = this.nzModalData.newsSource;
  }
}
