import { Component, inject, OnDestroy, OnInit, signal } from '@angular/core';
import {
  AbstractControl,
  FormGroup,
  NonNullableFormBuilder,
  ReactiveFormsModule,
  ValidationErrors,
  Validators,
} from '@angular/forms';
import { NzTabsModule } from 'ng-zorro-antd/tabs';
import { UserOutline, LockOutline, StepBackwardOutline } from '@ant-design/icons-angular/icons';
import { NzButtonModule } from 'ng-zorro-antd/button';
import { NzCheckboxModule } from 'ng-zorro-antd/checkbox';
import { NzFormModule, NzFormTooltipIcon } from 'ng-zorro-antd/form';
import { NzInputModule } from 'ng-zorro-antd/input';
import { NzSelectModule } from 'ng-zorro-antd/select';
import { NzDividerModule } from 'ng-zorro-antd/divider';
import { NzIconModule } from 'ng-zorro-antd/icon';

import { states } from '../../../assets/states';

import * as firebase from 'firebase/compat/app';
import { getAuth, sendPasswordResetEmail } from 'firebase/auth';

import { Subject, throwError } from 'rxjs';
import { catchError, skipWhile, takeUntil, tap } from 'rxjs/operators';
import { User } from '../user.model';
import { UsersService } from 'src/app/services/users.service';
import { LoginComponent } from '../login/login.component';
import { AngularFireAuth } from '@angular/fire/compat/auth';
import { RouterLink } from '@angular/router';
import { NZ_MODAL_DATA } from 'ng-zorro-antd/modal';
import { DietsService } from 'src/app/services/diets.service';
import { Diet } from 'src/app/diet-grid/diet.model';
import { Mail, MailService } from 'src/app/services/mail.service';

const icons = [StepBackwardOutline, UserOutline, LockOutline];

@Component({
  selector: 'profile',
  imports: [
    LoginComponent,
    ReactiveFormsModule,
    RouterLink,
    NzButtonModule,
    NzCheckboxModule,
    NzFormModule,
    NzInputModule,
    NzSelectModule,
    NzDividerModule,
    NzIconModule,
    NzTabsModule,
    // NzIconModule.forChild(icons),
  ],
  standalone: true,
  templateUrl: './profile.component.html',
  styleUrl: './profile.component.scss',
})
export class ProfileComponent implements OnInit, OnDestroy {
  private fb = inject(NonNullableFormBuilder);
  private destroy$ = new Subject<void>();

  readonly nzModalData = inject(NZ_MODAL_DATA);

  statesList = states;
  dietsList: Diet[] = [];
  user: User = null;
  userDiet: Diet;

  loading = signal<boolean>(false);
  passwordReset = signal<boolean>(false);
  authMessage = '';

  profileForm = this.fb.group({
    name: this.fb.control(''),
    dietId: this.fb.control(''),
    state: this.fb.control(''),
    // country: this.fb.control(''),
    zipcode: this.fb.control(NaN, [Validators.maxLength(5), Validators.minLength(5)]),
  });

  passwordVisible = false;
  captchaTooltipIcon: NzFormTooltipIcon = {
    type: 'info-circle',
    theme: 'twotone',
  };

  constructor(
    private dietsSvc: DietsService,
    private mailSvc: MailService,
    public usersSvc: UsersService
  ) {}

  ngOnInit(): void {
    this.getDiets();

    this.usersSvc.userAuthData$.subscribe((userData) => {
      if (userData) {
        console.log('Got some raw data', userData);
        this.user = userData.multiFactor.user;
        console.log('Set user', this.user);
        if (this.user.email) {
          this.getSiteUser(this.user.email);
        }
      }
    });
  }

  ngOnDestroy(): void {
    console.log('Destroy Profile component');
    this.destroy$.next();
    this.destroy$.complete();
  }

  getDiets(): void {
    this.dietsSvc.fetchAllDiets().subscribe((diets) => {
      console.log('[PROFILE] Got and set the diets', diets);
      this.dietsList = diets;
    });
  }

  // signIn() {
  //   this.usersSvc.signInWithEmailAndPassword(
  //     this.loginForm.value.email,
  //     this.loginForm.value.password
  //   );
  // }

  signOut() {
    this.usersSvc.signOut().then((signOutData) => {
      console.log('[PROFILE] Signed out', signOutData);
      this.loading.set(false);
      this.user = null;
    });
  }

  resetPassword() {
    //const auth = getAuth();
    if (this.user.email) {
      this.usersSvc
        .sendResetPassword(this.user.email)
        .then(() => {
          this.passwordReset.set(true);
          this.authMessage = 'To reset your password, please check your email...';
          setTimeout(() => {
            this.user = null;
          }, 35000);
        })
        .catch((error) => {
          this.passwordReset.set(true);
          this.authMessage = `${error.code} - ${error.message}`;
        });
    }
  }

  updatePageAndForm(user: Partial<User>) {
    ['name', 'state', 'dietId', 'zipcode'].forEach((field) => {
      if (user[field]) {
        this.profileForm.get(field).setValue(user[field]);
        this.user[field] = user[field];
      }
    });
    if (user.dietId) this.userDiet = this.findDiet(user.dietId);
    // if (user.name) {
    //   this.profileForm.get('name').setValue(user.name);
    //   this.user.name = user.name;
    // }
    // if (user.state) {
    //   this.profileForm.get('state').setValue(user.state);
    //   this.user.state = user.state;
    // }
    // if (user.dietId) {
    //   this.profileForm.get('dietId').setValue(user.dietId);
    //   this.user.dietId = this.user.dietId;
    //   this.userDiet = this.findDiet(user.dietId);
    // }
    // if (user.zipcode) {
    //   this.profileForm.get('zipcode').setValue(user.zipcode);
    //   this.user.zipcode = user.zipcode;
    // }
  }

  getSiteUser(email: string) {
    this.usersSvc.fetchSiteUser(email).subscribe((siteUser) => {
      console.log('Got this siteuser', siteUser);
      console.log('And this is the ID', siteUser.id);
      const userData = siteUser;
      this.user = { ...this.user, ...userData, id: siteUser.id };
      console.log('And now full user is', this.user);
      this.updatePageAndForm(this.user);
    });
  }

  sendUserEmail() {
    const diet = this.findDiet(this.user.dietId);
    const email: Mail = {
      to: 'tonybrasunas@gmail.com', // this.user.email,
      message: {
        subject: '**Balanced Media Diet Profile Updated',
        text: `
        ${this.user.name},

        Your profile has been updated. 
        
        Email:        ${this.user.email}
        Media Diet:   ${diet.subtitle} (${diet.title})
        State:        ${this.user.state}
        Zip Code:     ${this.user.zipcode}
        `,
      },
    };
    this.mailSvc.sendEmail(email).subscribe((sent) => console.log('Email Sent', sent.id));
  }

  findDiet = (dietId: string) => this.dietsList.find((diet) => diet.id === dietId);

  updateUser(): void {
    this.loading.set(true);
    console.log('Update this siteUser!', this.profileForm.value);
    const newUser = { ...this.profileForm.value };
    this.usersSvc
      .updateUser(this.user.id, newUser)
      .pipe(
        catchError((err) => {
          console.error('Failed to update siteUser');
          return throwError(() => err);
        })
      )
      .subscribe((_) => {
        this.updatePageAndForm(newUser);
        this.sendUserEmail();
        this.loading.set(false);
      });
  }

  closeModal() {
    console.log('close the modal here');
    this.nzModalData.modalCloser();
  }

  // confirmationValidator(control: AbstractControl): ValidationErrors | null {
  //   if (!control.value) {
  //     return { required: true };
  //   } else if (control.value !== control.parent.controls['password'].value) {
  //     return { confirm: true, error: true };
  //   }
  //   return {};
  // }

  // getCaptcha(e: MouseEvent): void {
  //   e.preventDefault();
  // }
}
